<script setup lang="ts">
import {ref,reactive,computed,onMounted,watch,inject} from 'vue'
import {ElMessage} from 'element-plus'
import {http,allRows} from '../api/http'
import BaseSalaryReference from './BaseSalaryReference.vue'
const props=defineProps<{mode:string}>()
const rows=ref<any[]>([]),employees=ref<any[]>([]),departments=ref<any[]>([]),report=ref<any>(null),busy=ref(false),page=ref(1),total=ref(0),dialog=ref(false),formRef=ref<any>(),editId=ref<number>(),form=reactive<any>({})
const month=ref(new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit'}).format(new Date())),year=ref(Number(month.value.slice(0,4))),employee=ref<number>(),department=ref<number>(),search=ref(''),status=ref(''),leaveType=ref(''),range=ref<string[]>([])
const salaryMonth=ref<number>()
const personal=computed(()=>props.mode.startsWith('/my/')),salary=computed(()=>props.mode.includes('salaries')),leaves=computed(()=>props.mode.includes('leaves')),rules=computed(()=>props.mode.endsWith('/rules')),supervisor=computed(()=>props.mode.startsWith('/supervisor/'))
const active=inject<any>('workspace-active',ref(true)),required=(label:string)=>[{required:true,message:`请填写${label}`,trigger:'blur'}]
const statusLabels:Record<string,string>={PENDING:'待审批',APPROVED:'已通过',REJECTED:'已驳回',CANCELLED:'已撤销'}
async function load(){
 busy.value=true
 try{
  const params:any={page:page.value,page_size:20,month:month.value,year:year.value,employee_id:employee.value,department_id:department.value,search:search.value||undefined,status:status.value||undefined,leave_type:leaveType.value||undefined,start_date:range.value?.[0],end_date:range.value?.[1]}
  let r:any
  if(props.mode==='/my/attendance'){report.value=(await http.get('/me/attendance',{params:{month:month.value}})).data;rows.value=[...report.value.daily].reverse();return}
  if(props.mode==='/hr/attendance/monthly')r=await http.get('/attendance/monthly',{params})
  else if(rules.value)r=await http.get('/attendance/rules')
  else if(salary.value)r=await http.get(personal.value?'/me/salaries':'/salaries',{params:{...params,month:personal.value?undefined:salaryMonth.value}})
  else if(leaves.value)r=await http.get(personal.value?'/me/leaves':supervisor.value?'/supervisor/leaves':'/hr/leaves',{params})
  else if(props.mode==='/supervisor/employees'){
    const ds=(await http.get('/departments')).data;const me=(await http.get('/auth/me')).data;const own=ds.find((d:any)=>d.supervisor_user_id===me.id)
    r=own?await http.get(`/departments/${own.id}/employees`,{params:{page:page.value,page_size:20}}):{data:[],total:0}
  }
  if(r){rows.value=r.data;total.value=r.total??r.data.length}
 }finally{busy.value=false}
}
onMounted(async()=>{departments.value=(await http.get('/departments')).data;if(props.mode.startsWith('/hr/'))employees.value=await allRows('/employees');await load()})
watch(active,(v:boolean)=>{if(v)load()})
function filter(){page.value=1;load()}
function open(row?:any){editId.value=row?.id;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,rules.value?{effective_date:'',weekdays:[0,1,2,3,4],start_time:'09:00',end_time:'18:00',late_grace_minutes:0,early_grace_minutes:0}:salary.value?{employee_id:undefined,year:year.value,month:Number(month.value.slice(5)),amount:'',remarks:''}:{leave_type:'事假',start_date:'',end_date:'',reason:''});if(row)for(const k of Object.keys(form))if(k in row)form[k]=row[k];dialog.value=true}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;const r=rules.value?await http.post('/attendance/rules',form):salary.value?editId.value?await http.patch(`/salaries/${editId.value}`,form):await http.post('/salaries',form):await http.post('/me/leaves',form);dialog.value=false;ElMessage.success(r.message||'保存成功');load()}
async function punch(type:string){await http.post(`/me/punch-${type}`);ElMessage.success('打卡成功');load()}
async function cancel(row:any){await http.post(`/me/leaves/${row.id}/cancel`);load()}
const reviewDialog=ref(false),reviewId=ref<number>(),decision=ref('approve'),note=ref('')
function review(row:any,action:string){reviewId.value=row.id;decision.value=action;note.value='';reviewDialog.value=true}
async function reviewSave(){await http.post(`/supervisor/leaves/${reviewId.value}/review`,{decision:decision.value,note:note.value||null});reviewDialog.value=false;ElMessage.success('审批完成');load()}
</script>
<template><section v-loading="busy"><div class="v3-toolbar"><el-date-picker v-if="!leaves&&!rules&&!salary&&mode!=='/supervisor/employees'" v-model="month" type="month" value-format="YYYY-MM" format="YYYY-MM" :clearable="false" aria-label="统计月份" @change="year=Number(month.slice(0,4));filter()"/><el-select v-if="salary&&!personal" v-model="salaryMonth" clearable placeholder="全部工资月份" @change="filter"><el-option v-for="m in 12" :key="m" :value="m" :label="`${m}月`"/></el-select><el-input-number v-if="salary" v-model="year" :min="2000" :max="2100" aria-label="工资年份" @change="filter"/><template v-if="mode.startsWith('/hr/')&&!rules"><el-select v-model="employee" clearable placeholder="全部员工" @change="filter"><el-option v-for="e in employees" :key="e.id" :label="`${e.name} · ${e.employee_no}`" :value="e.id"/></el-select><el-select v-if="!salary" v-model="department" clearable placeholder="全部部门" @change="filter"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id"/></el-select><el-input v-if="salary" v-model="search" placeholder="员工姓名／工号" clearable @change="filter"/></template><el-select v-if="leaves&&!personal" v-model="status" clearable placeholder="请假状态" @change="filter"><el-option v-for="(label,key) in statusLabels" :key="key" :value="key" :label="label"/></el-select><template v-if="mode==='/hr/leaves'"><el-select v-model="leaveType" clearable placeholder="请假类型" @change="filter"><el-option v-for="t in ['事假','病假','年假']" :key="t" :label="t" :value="t"/></el-select><el-date-picker v-model="range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" @change="filter"/></template><el-button v-if="rules||(!personal&&salary)||(personal&&leaves)" type="primary" @click="open()">{{rules?'新增规则版本':salary?'录入薪资':'申请请假'}}</el-button><el-button @click="load">刷新</el-button></div>
<template v-if="mode==='/my/attendance'"><div class="v3-toolbar"><el-button type="primary" @click="punch('in')">上班打卡</el-button><el-button @click="punch('out')">下班打卡</el-button><span class="v3-note">仅记录当前员工；时间采用公司时区服务器时间。</span></div><div class="v3-cards today-punch-cards" v-if="report?.today"><el-card><span>今日上班打卡 · {{report.today.date}}</span><strong class="today-punch-time">{{report.today.punch_in?.slice(11,19)||'未打卡'}}</strong></el-card><el-card><span>今日下班打卡 · {{report.today.date}}</span><strong class="today-punch-time">{{report.today.punch_out?.slice(11,19)||'未打卡'}}</strong></el-card></div><el-alert v-if="report?.today?.shift" class="v3-section" :title="`今日班次 ${report.today.shift.start_time} — ${report.today.shift.end_time}；迟到容忍 ${report.today.shift.late_grace_minutes} 分钟，早退容忍 ${report.today.shift.early_grace_minutes} 分钟`" type="info" :closable="false" show-icon/><el-alert v-if="report?.unconfigured_days" :title="`本月有 ${report.unconfigured_days} 天尚无生效规则；这些日期仅保留打卡，不判定迟到或缺勤。`" type="warning" :closable="false"/><div class="v3-cards" v-if="report"><el-card>本月已打卡天数<strong>{{report.raw_punch_days??rows.filter((d:any)=>d.punch_in).length}} 天</strong></el-card><el-card>规则统计：实际／应出勤<strong>{{report.actual_days}} / {{report.expected_days}}</strong></el-card><el-card>出勤率<strong>{{report.attendance_rate===null?'—':report.attendance_rate+'%'}}</strong></el-card><el-card>迟到／早退／缺卡<strong>{{report.late_count}} / {{report.early_count}} / {{report.missing_punch_count}}</strong></el-card></div><el-table :data="rows"><el-table-column prop="date" label="日期"/><el-table-column prop="punch_in" label="上班打卡"/><el-table-column prop="punch_out" label="下班打卡"/><el-table-column prop="status" label="状态"/></el-table></template>
<template v-else-if="mode==='/hr/attendance/monthly'"><p class="v3-note">出勤率＝实际出勤工作日 ÷（应出勤工作日－获批请假工作日）。不计未来工作日；分母为零显示 —。</p><el-table :data="rows"><el-table-column prop="employee_no" label="工号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="expected_days" label="应出勤"/><el-table-column prop="actual_days" label="实际出勤"/><el-table-column prop="approved_leave_days" label="获批请假"/><el-table-column prop="absent_days" label="缺勤"/><el-table-column prop="late_count" label="迟到"/><el-table-column prop="early_count" label="早退"/><el-table-column prop="missing_punch_count" label="缺卡"/><el-table-column label="出勤率"><template #default="{row}">{{row.attendance_rate===null?'—':row.attendance_rate+'%'}}</template></el-table-column></el-table></template>
<template v-else-if="rules"><p class="v3-note">规则按生效日保留版本，统计逐日选取当时有效规则。工作日 0 代表周一，6 代表周日。</p><el-table :data="rows"><el-table-column prop="effective_date" label="生效日期"/><el-table-column label="工作日"><template #default="{row}">{{row.weekdays.map((d:number)=>['一','二','三','四','五','六','日'][d]).join('、')}}</template></el-table-column><el-table-column prop="start_time" label="标准上班"/><el-table-column prop="end_time" label="标准下班"/><el-table-column prop="late_grace_minutes" label="迟到容忍（分钟）"/><el-table-column prop="early_grace_minutes" label="早退容忍（分钟）"/></el-table></template>
<template v-else-if="leaves"><p class="v3-note">{{mode==='/hr/leaves'?'HR 可查询全员请假记录；审批由对应部门主管执行。':supervisor?'仅可审批当前负责部门的待审申请，本人申请不可自审。':'按整工作日计算；部门尚无主管时申请保持待审批。'}}</p><el-table :data="rows"><el-table-column v-if="!personal" prop="name" label="姓名"/><el-table-column prop="leave_type" label="类型"/><el-table-column prop="start_date" label="开始日期"/><el-table-column prop="end_date" label="结束日期"/><el-table-column prop="reason" label="原因"/><el-table-column label="状态"><template #default="{row}">{{statusLabels[row.status]}}</template></el-table-column><el-table-column prop="reviewed_at" label="审批时间"/><el-table-column prop="review_note" label="审批备注"/><el-table-column v-if="personal||supervisor" label="操作" min-width="140"><template #default="{row}"><template v-if="row.status==='PENDING'"><el-button v-if="personal" text @click="cancel(row)">撤销</el-button><template v-else><el-button text @click="review(row,'approve')">通过</el-button><el-button text @click="review(row,'reject')">驳回</el-button></template></template></template></el-table-column></el-table></template>
<template v-else-if="salary"><BaseSalaryReference :personal="personal" :employee-id="employee" :search="search"/><h3>按月最终薪资记录</h3><p class="v3-note">所属年月为工资统计周期，金额为当月最终工资（元）。个人入口仅返回本人数据。</p><el-table :data="rows"><el-table-column v-if="!personal" prop="name" label="员工姓名"/><el-table-column prop="employee_no" label="工号"/><el-table-column prop="year" label="年份"/><el-table-column prop="month" label="月份"/><el-table-column prop="amount" label="最终薪资（元）"/><el-table-column prop="remarks" label="备注"/><el-table-column v-if="!personal" label="操作"><template #default="{row}"><el-button text @click="open(row)">编辑</el-button></template></el-table-column></el-table></template>
<el-table v-else :data="rows"><el-table-column prop="employee_no" label="工号"/><el-table-column prop="name" label="姓名"/><el-table-column prop="department_name" label="部门"/><el-table-column prop="position_name" label="职位"/><el-table-column prop="grade" label="职级"/><el-table-column prop="hire_date" label="入职日期"/></el-table>
<el-pagination v-if="total>20&&!rules" class="v3-pagination" layout="prev,pager,next,total" :total="total" :page-size="20" v-model:current-page="page" @current-change="load"/>
<el-dialog v-model="dialog" :title="rules?'新增考勤规则版本':salary?'薪资录入':'申请请假'" width="540px" destroy-on-close><el-form ref="formRef" :model="form" label-position="top" class="v3-form" @submit.prevent="save"><template v-if="rules"><el-form-item label="生效日期" prop="effective_date" :rules="required('生效日期')"><el-date-picker v-model="form.effective_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="工作日" prop="weekdays" :rules="required('工作日')"><el-checkbox-group v-model="form.weekdays"><el-checkbox v-for="(d,i) in ['周一','周二','周三','周四','周五','周六','周日']" :key="i" :value="i">{{d}}</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="标准上班时间" prop="start_time" :rules="required('时间')"><el-time-picker v-model="form.start_time" value-format="HH:mm" format="HH:mm"/></el-form-item><el-form-item label="标准下班时间" prop="end_time" :rules="required('时间')"><el-time-picker v-model="form.end_time" value-format="HH:mm" format="HH:mm"/></el-form-item><el-form-item label="迟到容忍分钟"><el-input-number v-model="form.late_grace_minutes" :min="0" :max="240"/></el-form-item><el-form-item label="早退容忍分钟"><el-input-number v-model="form.early_grace_minutes" :min="0" :max="240"/></el-form-item></template>
<template v-else-if="salary"><el-form-item label="员工" prop="employee_id" :rules="required('员工')"><el-select v-model="form.employee_id" filterable><el-option v-for="e in employees" :key="e.id" :value="e.id" :label="`${e.name} · ${e.employee_no}`"/></el-select></el-form-item><el-form-item label="工资年份"><el-input-number v-model="form.year" :min="2000" :max="2100"/></el-form-item><el-form-item label="工资月份"><el-input-number v-model="form.month" :min="1" :max="12"/></el-form-item><el-form-item label="最终薪资金额（元）" prop="amount" :rules="required('金额')"><el-input v-model="form.amount" placeholder="例如 5000.00"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remarks" type="textarea"/></el-form-item></template>
<template v-else><el-form-item label="请假类型" prop="leave_type" :rules="required('类型')"><el-select v-model="form.leave_type"><el-option v-for="t in ['事假','病假','年假']" :key="t" :label="t" :value="t"/></el-select></el-form-item><el-form-item label="开始日期" prop="start_date" :rules="required('开始日期')"><el-date-picker v-model="form.start_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="结束日期" prop="end_date" :rules="required('结束日期')"><el-date-picker v-model="form.end_date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="请假原因" prop="reason" :rules="required('原因')"><el-input v-model="form.reason" type="textarea"/></el-form-item></template><div class="dialog-actions"><el-button @click="dialog=false">取消</el-button><el-button type="primary" native-type="submit">保存</el-button></div></el-form></el-dialog>
<el-dialog v-model="reviewDialog" :title="decision==='approve'?'通过请假':'驳回请假'" width="450px"><el-input v-model="note" type="textarea" placeholder="审批备注（可选）"/><template #footer><el-button @click="reviewDialog=false">取消</el-button><el-button type="primary" @click="reviewSave">确认审批</el-button></template></el-dialog>
</section></template>
